    }
    enableDragScroll(document.getElementById('testimonialsTrack'));
    enableDragScroll(document.getElementById('awardsTrack'));

    // Services accordion rows
    document.querySelectorAll('.services .row').forEach(row => {
      const top = row.querySelector('.r-top');
      const toggle = () => {
        const open = row.dataset.open === "true";
        row.dataset.open = open ? "false" : "true";
        top.setAttribute('aria-expanded', row.dataset.open === "true" ? "true" : "false");
      };
      top.addEventListener('click', toggle);
      top.addEventListener('keydown', (e) => {
        if(e.key === 'Enter' || e.key === ' '){
          e.preventDefault();
          toggle();
        }
      });
    });

    // Filterable journal
    const journalGrid = document.getElementById('journalGrid');
    const journalBtns = Array.from(document.querySelectorAll('[data-filter]'));
    function setJournalFilter(filter){
      journalBtns.forEach(b => b.setAttribute('aria-pressed', b.dataset.filter === filter ? 'true' : 'false'));
      const cards = Array.from(journalGrid.querySelectorAll('.article'));
      cards.forEach((c, idx) => {
        const show = filter === 'all' || c.dataset.cat === filter;
        c.style.transitionDelay = (idx % 6) * 35 + 'ms';
        if(show){
          c.classList.remove('fade');
          c.style.display = '';
          requestAnimationFrame(()=> c.style.opacity = '');
        }else{
          c.classList.add('fade');
          setTimeout(()=> { c.style.display = 'none'; }, 240);
        }
      });
    }
    journalBtns.forEach(b => b.addEventListener('click', ()=> setJournalFilter(b.dataset.filter)));

    // Filterable case studies
    const caseGrid = document.getElementById('caseGrid');
    const caseBtns = Array.from(document.querySelectorAll('[data-case]'));
    function setCaseFilter(filter){
      caseBtns.forEach(b => b.setAttribute('aria-pressed', b.dataset.case === filter ? 'true' : 'false'));
      const cards = Array.from(caseGrid.querySelectorAll('.case'));
      cards.forEach((c, idx) => {
        const show = filter === 'all' || c.dataset.sector === filter;
        c.style.transitionDelay = (idx % 6) * 35 + 'ms';
        if(show){
          c.classList.remove('fade');
          c.style.display = '';
        }else{
          c.classList.add('fade');
          setTimeout(()=> { c.style.display = 'none'; }, 240);
        }
      });
    }
    caseBtns.forEach(b => b.addEventListener('click', ()=> setCaseFilter(b.dataset.case)));

    // Inquiry toast
    const submitBtn = document.getElementById('submitInquiry');
    const toast = document.getElementById('toast');
    submitBtn.addEventListener('click', () => {
      toast.style.display = 'block';
      toast.animate(
        [{opacity:0, transform:'translateY(6px)'},{opacity:1, transform:'translateY(0px)'}],
        {duration: 380, easing: 'cubic-bezier(.2,.85,.2,1)'}
      );
      setTimeout(()=> {
        toast.animate(
          [{opacity:1, transform:'translateY(0px)'},{opacity:0, transform:'translateY(6px)'}],
          {duration: 340, easing: 'cubic-bezier(.2,.85,.2,1)'}
        ).onfinish = () => { toast.style.display = 'none'; };
      }, 4200);
    });

    // Footer year
    document.getElementById('year').textContent = new Date().getFullYear();

    // QR-like grid generation (deterministic pattern)
    const qrGrid = document.getElementById('qrGrid');
    const seed = 4127;
    function rand(i){
      // simple deterministic pseudo-random
      return (Math.sin((i+seed) * 12.9898) * 43758.5453) % 1;
    }
    const size = 9*9;
    for(let i=0;i<size;i++){
      const cell = document.createElement('i');
      const r = rand(i);
      const row = Math.floor(i/9), col = i%9;
      const finder = (row<3 && col<3) || (row<3 && col>5) || (row>5 && col<3);
      const timing = (row===4 || col===4);
      const on = finder ? ((row===1||col===1||row===0||col===0||row===2||col===2) ? true : false) : (timing ? (i%2===0) : (r>0.58));
      if(on) cell.classList.add('on');
      qrGrid.appendChild(cell);
    }

    // Smooth anchor scrolling (native-ish)
    document.querySelectorAll('a[href^="#"]').forEach(a=>{
      a.addEventListener('click', (e)=>{
        const id = a.getAttribute('href');
        if(!id || id === '#') return;
        const target = document.querySelector(id);
        if(!target) return;
        e.preventDefault();
        target.scrollIntoView({behavior:'smooth', block:'start'});
        closeAll(null);
      });
    });

    // Keyboard activation for role items
