class Node:
    def __init__(self, tag, attrs, start, parent=None):
        self.tag=tag; self.attrs=dict(attrs); self.start=start; self.parent=parent; self.children=[]; self.end=None; self.close=None
    def has(self, cls): return cls in self.attrs.get('class','').split()

class Document(HTMLParser):
    def __init__(self, source):
        super().__init__(convert_charrefs=False)
        self.source=source; self.nodes=[]; self.stack=[]; self.lines=[0]
        self.lines.extend(m.end() for m in re.finditer('\\n',source))
        self.feed(source)
    def offset(self):
        line,col=self.getpos();return self.lines[line-1]+col
    def handle_starttag(self,tag,attrs):
        start=self.offset(); parent=self.stack[-1] if self.stack else None
        node=Node(tag,attrs,start,parent)
        if parent:parent.children.append(node)
        self.nodes.append(node)
        if tag in {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}:
            node.end=start+len(self.get_starttag_text());node.close=node.end
        else:self.stack.append(node)
    def handle_startendtag(self,tag,attrs):
        self.handle_starttag(tag,attrs)
        if self.stack and self.stack[-1].start==self.offset():
            node=self.stack.pop();node.end=node.start+len(self.get_starttag_text());node.close=node.end
    def handle_endtag(self,tag):
        for i in range(len(self.stack)-1,-1,-1):
            if self.stack[i].tag==tag:
                node=self.stack[i]; node.close=self.offset();node.end=self.source.index('>',node.close)+1
                del self.stack[i:];break
    def one(self,predicate):
        matches=[n for n in self.nodes if predicate(n)]
        assert len(matches)==1, len(matches)
        return matches[0]

